/* Connected engineering department workflow. All approvals are demo records. */
"use strict";
const ENGINEERING_TEAMS=[
 {role:"flightops",user:"flightops.demo",name:"Flight operations / flight crew",owns:"Flight-sector utilisation source, crew technical-log references and handover to maintenance control",next:"Maintenance control / technical records"},
 {role:"procurement",user:"procurement.demo",name:"Procurement & suppliers",owns:"Supplier review, purchase orders, transport and shortage follow-up",next:"Stores receipt"},
 {role:"stores",user:"m.faith",name:"Technical stores",owns:"Part master, receipts, quarantine, bins, serial allocation, custody, dispatch and segregation",next:"Technical records / receiving inspection"},
 {role:"records",user:"records.demo",name:"Technical records",owns:"Logbook reconciliation, source data, life limits, release references and completed work archive",next:"Independent inspection / planning"},
 {role:"inspector",user:"k.moyo",name:"Quality & receiving inspection",owns:"Incoming condition, release evidence, independent life review, NDT disposition and calibration",next:"Serviceable stores / maintenance"},
 {role:"planner",user:"planning.demo",name:"Maintenance planning",owns:"Due-list review, maintenance data revision, work packages, personnel, bays, tools and serial demand",next:"Maintenance control / stores issue"},
 {role:"control",user:"control.demo",name:"Maintenance control",owns:"Aircraft technical status, AOG coordination, work authorisation and unresolved-item handover",next:"Line / base maintenance"},
 {role:"engineer",user:"t.ndlovu",name:"Line & base engineering",owns:"Defect work, installation/removal, utilisation entry, task evidence and shift handover",next:"Independent inspection / certifying staff"},
 {role:"workshop",user:"workshop.demo",name:"Component workshop / external MRO",owns:"Repair assessment, shop work, test/overhaul report and return to quarantine",next:"Stores / records / receiving inspection"},
 {role:"certifier",user:"certifier.demo",name:"Certifying staff",owns:"Review work completion, independent checks, outstanding defects and demonstration certification",next:"Technical records archive"},
 {role:"reliability",user:"reliability.demo",name:"Reliability & engineering support",owns:"Repeat removals, lab findings, engineering instructions and corrective-action follow-up",next:"Planning / maintenance control"}
];
for(const t of ENGINEERING_TEAMS)if(!STORE.users.some(u=>u.user===t.user)){STORE.users.push({user:t.user,pass:"demo123",role:t.role,name:t.name,title:t.name});if(!STORE.profiles.some(p=>p.user===t.user))STORE.profiles.push({user:t.user,id:`AZ-${t.role.toUpperCase()}`,name:t.name,department:t.name,specialty:t.owns,shift:"Day shift",authority:"Demonstration only"});}
STORE.purchaseOrders=[];STORE.workPackages=[];STORE.shopOrders=[];STORE.handovers=[];STORE.instructions=[];STORE.materialLots=[];STORE.flightReports=[];STORE.deferrals=[];
try{const data=JSON.parse(localStorage.getItem(OPS_KEY));if(data?.version===2)for(const key of ["purchaseOrders","workPackages","shopOrders","handovers","instructions","materialLots","flightReports","deferrals","resources"])if(Array.isArray(data[key]))STORE[key]=data[key];}catch(e){console.warn("Department records unavailable",e.message);}
const CHAIN_KEYS=["fleet","components","profiles","jobs","audit","movements","defects","planningRates","parts","calibrations","lifeReviews","labTests","qualityFindings","resources","purchaseOrders","workPackages","shopOrders","handovers","instructions","materialLots","flightReports","deferrals"];
function refreshRegisteredHolding(){for(const p of STORE.parts.filter(p=>p.category)){if(p.category==="Consumable / standard part")p.stock=STORE.materialLots.filter(l=>l.pn===p.pn&&l.condition==="Serviceable"&&l.expiry>demoDate).reduce((n,l)=>n+l.qty,0);else if(p.category==="Controlled tool")p.stock=STORE.resources.filter(r=>r.pn===p.pn&&currentCalibration(r.id).usable).length;else p.stock=STORE.components.filter(c=>c.pn===p.pn&&c.reg==="Stores"&&c.condition==="Serviceable"&&!c.issue&&!c.shopOpen&&!c.scrapped&&componentState(c).status!=="OVERDUE").length;}}
persistOps=function(){try{refreshRegisteredHolding();const data={version:2};for(const key of CHAIN_KEYS)data[key]=STORE[key];localStorage.setItem(OPS_KEY,JSON.stringify(data));}catch(e){toast("warn","Local storage unavailable","Export records before leaving this session.");}};
function chainId(prefix){return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,6)}`;}
function safeWorkflowRef(ref){return typeof ref==="string"&&/^[A-Za-z0-9_./: -]{1,80}$/.test(ref);}
function chainActor(){return {by:session.user,at:new Date().toISOString()};}
function chainGuard(roles){return technicalRole(roles);}
function chainEvidence(action,reference,notes){if(!reference?.trim()||!notes?.trim())throw Error("A document/work reference and meaningful notes are required.");return {action,reference:reference.trim(),notes:notes.trim(),...chainActor()};}
function chainFields(fields){return fields.map(([id,label,type="text",value=""])=>`<label for="chain_${id}">${label}</label>${type==="textarea"?`<textarea id="chain_${id}" required maxlength="600">${esc(value)}</textarea>`:`<input id="chain_${id}" type="${type}" value="${esc(value)}" ${type==="number"?'min="0" step="any"':""} required maxlength="120">`}`).join("");}
function chainForm(title,action,body){engineeringModal(title,`<form onsubmit="event.preventDefault();${action}">${body}<p id="chainError" class="field-err" role="alert"></p><button class="btn-primary">Save departmental record</button></form>`);}
function chainFail(e){$("chainError").textContent=e.message;}
function chainValue(id){return $("chain_"+id).value.trim();}
function finiteLimit(value){return value==null?Infinity:value;}
// Limit applicability is explicit; on-condition articles do not receive invented retirement lives.
componentState=function(c){const hours=Math.min(finiteLimit(c.hLimit)-c.hours,finiteLimit(c.retireHours)-c.totalHours),cycles=Math.min(finiteLimit(c.cLimit)-c.cycles,finiteLimit(c.retireCycles)-c.totalCycles),flights=c.fLimit==null?null:c.fLimit-c.flights,days=c.due?Math.ceil((Date.parse(c.due+"T00:00:00Z")-Date.parse(new Date().toISOString().slice(0,10)+"T00:00:00Z"))/86400000):Infinity;return {hours,cycles,flights,days,status:!Number.isFinite(hours)&&!Number.isFinite(cycles)&&!Number.isFinite(days)&&flights===null?"ON CONDITION":hours<=0||cycles<=0||days<=0||flights!==null&&flights<=0?"OVERDUE":hours<=200||cycles<=100||days<=30||flights!==null&&flights<=100?"DUE SOON":"WITHIN LIMITS"};};
forecastComponent=function(c,hpd,cpd){const s=componentState(c),bounds=[{basis:"Calendar",days:s.days}];if(hpd>0)bounds.push({basis:"Hours",days:s.hours/hpd});if(cpd>0){bounds.push({basis:"Cycles",days:s.cycles/cpd});if(s.flights!==null)bounds.push({basis:"Flights",days:s.flights/cpd});}const applicable=bounds.filter(b=>Number.isFinite(b.days));if(!applicable.length)return {basis:"On condition",days:null,date:"No fixed interval",status:s.status};const first=applicable.reduce((a,b)=>a.days<=b.days?a:b),days=Math.max(0,Math.floor(first.days));return {basis:first.basis,days,date:relativeDate(days),status:s.status};};
function validateMaster(p){if(!/^[A-Z0-9_.-]+$/.test(p.pn)||STORE.parts.some(x=>x.pn.toUpperCase()===p.pn.toUpperCase()))throw Error("Use a unique part number with letters, digits, dots, hyphens or underscores.");if(!p.name||!/^\d{2}$/.test(p.ata)||!p.loc||!Number.isInteger(p.min)||p.min<0)throw Error("Complete description, two-digit ATA, location and whole-number minimum.");if(!["Life-controlled component","On-condition component","Consumable / standard part","Controlled tool"].includes(p.category))throw Error("Select an article category.");return p;}
function openPartMaster(){if(!chainGuard(["stores"]))return;chainForm("Register new equipment / part master","savePartMaster()",`${chainFields([["pn","Part / equipment model number"],["name","Description"],["ata","ATA chapter (two digits)"],["loc","Storage bin / location"],["min","Minimum holding","number","1"]])}<label for="chain_category">Article category</label><select id="chain_category"><option>Life-controlled component</option><option>On-condition component</option><option>Consumable / standard part</option><option>Controlled tool</option></select><p class="form-note">The master identifies the model. Each component receipt creates a separate serial and its own life record; materials use lots, tools use asset records.</p>`);}
function savePartMaster(){if(!chainGuard(["stores"]))return;const p={pn:chainValue("pn").toUpperCase(),name:chainValue("name"),ata:chainValue("ata"),loc:chainValue("loc"),min:Number(chainValue("min")),category:chainValue("category"),stock:0,unit:0,life:"PENDING",cert:"Receipt-specific",createdBy:session.user};try{validateMaster(p);}catch(e){chainFail(e);return;}STORE.parts.push(p);auditOps("Part master registered",p.pn,p.category);closeModal();route("#intake");}
function validateIntake(c,components=STORE.components){if(!/^[A-Za-z0-9_-]+$/.test(c.sn)||components.some(x=>x.sn.toUpperCase()===c.sn.toUpperCase()))throw Error("Use a unique serial with letters, digits, hyphens or underscores.");const p=STORE.parts.find(p=>p.pn===c.pn);if(!p||["Controlled tool","Consumable / standard part"].includes(p.category))throw Error("Use the tool or material-lot receipt workflow for this category.");if(p.category==="Life-controlled component"&&c.controlMode!=="Life-controlled"||p.category==="On-condition component"&&c.controlMode!=="On condition")throw Error("Receipt control mode must match the registered article category.");for(const k of ["hours","cycles","flights","totalHours","totalCycles","totalFlights"])if(!Number.isFinite(c[k])||c[k]<0||(k.toLowerCase().includes("cycles")||k.toLowerCase().includes("flights"))&&!Number.isInteger(c[k]))throw Error("Enter non-negative usage; cycles and flights must be whole numbers.");if(c.totalHours<c.hours||c.totalCycles<c.cycles||c.totalFlights<c.flights)throw Error("Since-new usage cannot be less than since-overhaul usage.");for(const k of ["hLimit","cLimit","fLimit","retireHours","retireCycles"])if(c[k]!=null&&(!Number.isFinite(c[k])||c[k]<=0||["cLimit","fLimit","retireCycles"].includes(k)&&!Number.isInteger(c[k])))throw Error("Applicable limits must be positive; cycles and flights must be whole numbers.");if(c.controlMode==="Life-controlled"&&![c.hLimit,c.cLimit,c.fLimit,c.retireHours,c.retireCycles,c.due].some(v=>v!=null))throw Error("Life-controlled equipment requires at least one applicable approved limit.");if(!validQualityDate(c.lastOverhaul)||c.lastOverhaul>demoDate||c.due&&(!validQualityDate(c.due)||c.due<=c.lastOverhaul))throw Error("Check last overhaul and applicable calendar removal date.");for(const k of ["release","originJob","supplier","po","limitSource","limitRevision","historyReference"])if(!c[k]?.trim())throw Error("Complete supplier, purchase/receipt, release, source revision and history references.");const order=STORE.purchaseOrders.find(p=>p.ref===c.po);if(order&&(order.pn!==c.pn||order.supplier!==c.supplier||order.receipts.length>=order.qty&&!order.receipts.includes(c.sn)))throw Error("Purchase order part, supplier or remaining ordered quantity does not match this receipt.");return c;}
function openReceipt(){if(!chainGuard(["stores"]))return;const parts=STORE.parts.filter(p=>!["Controlled tool","Consumable / standard part"].includes(p.category));chainForm("Stores: receive component & establish life baseline","saveReceipt()",`<label for="chain_part">Catalogue part</label><select id="chain_part">${parts.map(p=>`<option value="${esc(p.pn)}">${esc(p.pn)} · ${esc(p.name)}</option>`).join("")}</select><div class="form-grid">${chainFields([["sn","Unique serial"],["supplier","Supplier / repair organisation"],["po","Purchase order / repair order"],["receipt","Goods receipt / origin job"],["release","Release document reference"],["history","Logbook / previous-life history reference"],["limitSource","Approved limit source (CMM / ALS / programme)"],["revision","Source revision"],["hours","Hours since overhaul (TSO)","number","0"],["cycles","Cycles since overhaul (CSO)","number","0"],["flights","Flights since overhaul","number","0"],["totalHours","Total hours since new (TSN)","number","0"],["totalCycles","Total cycles since new (CSN)","number","0"],["totalFlights","Total flights since new","number","0"],["overhaul","Last overhaul / manufacture baseline","date",demoDate]])}</div><label for="chain_mode">Control mode</label><select id="chain_mode"><option>Life-controlled</option><option>On condition</option></select><p class="form-note">Leave non-applicable limits blank. Stores transcribes source data; Technical Records verifies its applicability before inspection. A check interval is not automatically a retirement limit.</p><div class="form-grid">${[["hLimit","Overhaul hour interval"],["cLimit","Overhaul cycle interval"],["fLimit","Overhaul flight interval"],["retireHours","Mandatory retirement hours"],["retireCycles","Mandatory retirement cycles"]].map(([id,label])=>`<div><label for="chain_${id}">${label} (if applicable)</label><input id="chain_${id}" type="number" min="1" step="any"></div>`).join("")}<div><label for="chain_due">Calendar removal date (if applicable)</label><input id="chain_due" type="date"></div></div>`);}
function receiveIntake(c){validateIntake(c);c.intakeId=chainId("GRN");c.intakeBaseline=JSON.parse(JSON.stringify(c));c.reg="Stores";c.position="Receiving quarantine";c.condition="Quarantined";c.stockCounted=false;c.recordsVerified=false;c.receivedBy=session.user;c.receivedAt=new Date().toISOString();c.basis="overhaul";c.authority="Pending departmental checks";c.modState="Pending inspection";c.rectification="Received; verification pending";c.releaseDate=demoDate;STORE.components.push(c);return c;}
function saveReceipt(){if(!chainGuard(["stores"]))return;const c={pn:chainValue("part"),sn:chainValue("sn").toUpperCase(),supplier:chainValue("supplier"),po:chainValue("po"),originJob:chainValue("receipt"),release:chainValue("release"),historyReference:chainValue("history"),limitSource:chainValue("limitSource"),limitRevision:chainValue("revision"),controlMode:chainValue("mode"),lastOverhaul:chainValue("overhaul"),due:chainValue("due")||null};for(const k of ["hours","cycles","flights","totalHours","totalCycles","totalFlights"])c[k]=Number(chainValue(k));for(const k of ["hLimit","cLimit","fLimit","retireHours","retireCycles"])c[k]=chainValue(k)?Number(chainValue(k)):null;try{receiveIntake(c);}catch(e){chainFail(e);return;}recordMovement("Stores receipt",c,c.supplier,"Receiving quarantine",c.originJob);const po=STORE.purchaseOrders.find(p=>p.ref===c.po);if(po){po.receipts=po.receipts||[];po.receipts.push(c.sn);po.status=po.receipts.length>=po.qty?"Received":"Part received";persistOps();}closeModal();route("#intake");}
function openRecordsVerify(sn){if(!chainGuard(["records"]))return;const c=STORE.components.find(x=>x.sn===sn);chainForm("Technical records: reconcile receipt baseline",`saveRecordsVerify('${sn}')`,`<p><b>${esc(sn)}</b> · ${esc(c.limitSource)} rev ${esc(c.limitRevision)}<br>TSO ${c.hours} / CSO ${c.cycles}; TSN ${c.totalHours} / CSN ${c.totalCycles}.</p>${chainFields([["reference","Verified source / logbook reference"],["notes","Applicability and counter reconciliation notes","textarea"]])}<label><input id="chain_check" type="checkbox" required> Identity, life history, source revision, applicable limits and overhaul basis checked</label><p class="form-note">Stores entry remains retained as the intake baseline. Corrections require a new supporting record; no limits are inferred from aircraft type.</p>`);}
function verifyRecords(c,reference,notes){validateIntake(c,STORE.components.filter(x=>x.sn!==c.sn));const evidence=chainEvidence("Records verified",reference,notes);c.recordsVerified=true;c.recordsEvidence=evidence;c.recordsSnapshot=lifeSnapshot(c);return evidence;}
function saveRecordsVerify(sn){if(!chainGuard(["records"])||!$("chain_check").checked)return;const c=STORE.components.find(x=>x.sn===sn);try{verifyRecords(c,chainValue("reference"),chainValue("notes"));}catch(e){chainFail(e);return;}auditOps("Receipt life baseline verified",sn,chainValue("reference"));closeModal();route("#intake");}
function openBaselineCorrection(sn){if(!chainGuard(["records"]))return;const c=STORE.components.find(c=>c.sn===sn);if(c.reg!=="Stores"||c.condition!=="Quarantined"||c.shopOpen){toast("warn","Record correction","Receipt correction requires quarantine and stores custody.");return;}chainForm("Correct transcribed receipt data with evidence",`saveBaselineCorrection('${sn}')`,`${chainFields([["reference","Corrected source / revision reference"],["notes","Reason, discrepancy and corrected evidence","textarea"]])}<div class="form-grid">${["hours","cycles","flights","totalHours","totalCycles","totalFlights","hLimit","cLimit","fLimit","retireHours","retireCycles"].map(k=>`<div><label for="chain_${k}">${esc(k)}${k.includes("Limit")||k.startsWith("retire")?" (blank = not applicable)":""}</label><input id="chain_${k}" type="number" min="0" step="any" value="${c[k]??""}" ${!["hLimit","cLimit","fLimit","retireHours","retireCycles"].includes(k)?"required":""}></div>`).join("")}</div><p>The original stores baseline is retained. Corrections invalidate technical-records verification and inspector acceptance.</p>`);}
function correctBaseline(c,values,reference,notes){if(c.reg!=="Stores"||c.condition!=="Quarantined"||c.shopOpen||c.scrapped)throw Error("Correct only quarantined receipt records in stores custody.");const evidence=chainEvidence("Transcription corrected",reference,notes),candidate={...c,...values};validateIntake(candidate,STORE.components.filter(x=>x.sn!==c.sn));c.corrections=c.corrections||[];c.corrections.push({...evidence,before:lifeSnapshot(c),after:lifeSnapshot(candidate)});Object.assign(c,values);c.recordsVerified=false;delete c.inspectedBy;return c;}
function saveBaselineCorrection(sn){if(!chainGuard(["records"]))return;const c=STORE.components.find(c=>c.sn===sn),values={};for(const k of ["hours","cycles","flights","totalHours","totalCycles","totalFlights"])values[k]=Number(chainValue(k));for(const k of ["hLimit","cLimit","fLimit","retireHours","retireCycles"])values[k]=chainValue(k)?Number(chainValue(k)):null;try{correctBaseline(c,values,chainValue("reference"),chainValue("notes"));}catch(e){chainFail(e);return;}auditOps("Receipt transcription corrected",sn,chainValue("reference"));closeModal();route("#intake");}
const qualityBeforeRecords=canQualityApprove;
canQualityApprove=function(c){qualityBeforeRecords(c);if(c.intakeId&&!c.recordsVerified)throw Error("Technical Records must reconcile this receipt's life baseline before quality acceptance.");if(c.shopOpen||c.scrapped)throw Error("Shop custody or scrap segregation prevents acceptance.");return true;};
const qualitySaveBeforeStock=saveQuality;
saveQuality=function(sn){const c=STORE.components.find(x=>x.sn===sn);const before=c?.condition;qualitySaveBeforeStock(sn);if(before==="Quarantined"&&c.condition==="Serviceable"&&c.stockCounted===false){STORE.parts.find(p=>p.pn===c.pn).stock++;c.stockCounted=true;persistOps();}};
function intakeStage(c){if(c.scrapped)return "Scrap segregated";if(c.shopOpen)return "Workshop / repair vendor";if(c.reg!=="Stores")return "Installed · engineering & records";if(c.intakeId&&!c.recordsVerified)return "Technical records verification";if(c.condition==="Quarantined")return "Receiving / return inspection";if(lifeReviewState(c)!=="Reviewed current record")return "Independent life inspection";if(c.issue)return "Issued to work package";return "Serviceable · awaiting demand";}
function viewIntake(){ refreshRegisteredHolding();$("viewSub").textContent="Stores creates the equipment identity and source-life baseline. Every department works from that serial record; quarantine is excluded from available stock.";$("viewActions").innerHTML=session.role==="stores"?'<button class="btn" onclick="openPartMaster()">+ New equipment model</button><button class="btn btn-accent" onclick="openReceipt()">+ Receive component</button><button class="btn" onclick="openMaterialReceipt()">+ Material / tool receipt</button>':"";$("viewBody").innerHTML=`<div class="workflow-strip"><span>Stores records identity & source life</span><span>Records reconciles limits & history</span><span>Inspector accepts & reviews life</span><span>Planner → stores issue → engineer</span></div>${engPanel("Incoming equipment & departmental ownership",engTable(["Serial / part","Receipt / source","Current owner / stage","Remaining life","Next action"],STORE.components.map(c=>{const s=componentState(c);return `<tr><td><b>${esc(c.sn)}</b><small class="table-sub">${esc(c.pn)}</small></td><td>${esc(c.originJob)}<small class="table-sub">${esc(c.limitSource||"Seeded demo source")} ${esc(c.limitRevision||"")}</small></td><td>${engTag(intakeStage(c),c.condition==="Quarantined"?"warnb":"info")}</td><td>${Number.isFinite(s.hours)?s.hours+" FH":"Hours N/A"} / ${Number.isFinite(s.cycles)?s.cycles+" FC":"Cycles N/A"}<small class="table-sub">${esc(s.status)}</small></td><td><button class="btn btn-sm" onclick="openChainPassport('${c.sn}')">Full record</button>${session.role==="records"&&c.intakeId&&!c.recordsVerified?`<button class="btn btn-sm" onclick="openRecordsVerify('${c.sn}')">Verify baseline</button><button class="btn btn-sm" onclick="openBaselineCorrection('${c.sn}')">Correct transcription</button>`:""}${session.role==="inspector"&&c.condition==="Quarantined"&&!c.shopOpen?`<button class="btn btn-sm" onclick="openQuality('${c.sn}')">Inspect receipt</button>`:""}${session.role==="inspector"&&c.condition==="Serviceable"?`<button class="btn btn-sm" onclick="openLifeInspection('${c.sn}')">Inspect life</button>`:""}</td></tr>`;}).join("")))}${engPanel("Equipment model register",engTable(["Part / description","Category","ATA / bin","Available holding"],STORE.parts.filter(p=>p.category).map(p=>`<tr><td>${esc(p.pn)}<small class="table-sub">${esc(p.name)}</small></td><td>${esc(p.category)}</td><td>${esc(p.ata)} / ${esc(p.loc)}</td><td>${p.stock}</td></tr>`).join("")))}${engPanel("Materials & lot custody",engTable(["Lot / part","Received / remaining","Shelf expiry","Condition","Action"],STORE.materialLots.map(l=>`<tr><td>${esc(l.lot)} / ${esc(l.pn)}</td><td>${l.received} / ${l.qty}</td><td>${esc(l.expiry)}</td><td>${engTag(l.condition,l.condition==="Serviceable"?"ok":"warnb")}</td><td>${session.role==="inspector"&&l.condition==="Quarantined"?`<button class="btn btn-sm" onclick="openLotInspect('${l.id}')">Inspect lot</button>`:""}${session.role==="stores"&&l.condition==="Serviceable"?`<button class="btn btn-sm" onclick="openLotIssue('${l.id}')">Issue lot</button>`:""}</td></tr>`).join("")))}`;}
function openChainPassport(sn){const c=STORE.components.find(x=>x.sn===sn),b=c.intakeBaseline;engineeringModal("Serial master & chain of custody",`<h3>${esc(sn)} · ${esc(c.pn)}</h3><p>${esc(intakeStage(c))}</p>${engTable(["Source record","Value"],Object.entries({Supplier:c.supplier,Order:c.po,"Goods receipt":c.originJob,"Approved limit source":c.limitSource,"Revision":c.limitRevision,"Life history":c.historyReference,"Received by":c.receivedBy,"Receipt time":c.receivedAt,"Baseline TSO / TSN":b?`${b.hours} / ${b.totalHours}`:"Seeded record","Current TSO / TSN":`${c.hours} / ${c.totalHours}`,"Records verified by":c.recordsEvidence?.by,"Records evidence":c.recordsEvidence?.reference}).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v??"—")}</td></tr>`).join(""))}${engTable(["Time","Action / reference","Owner / notes"],STORE.audit.filter(a=>a.reference===sn||a.details?.includes(sn)).map(a=>`<tr><td>${esc(a.at)}</td><td>${esc(a.action)}<small class="table-sub">${esc(a.reference)}</small></td><td>${esc(a.by)}<small class="table-sub">${esc(a.details)}</small></td></tr>`).join(""))}<button class="btn" onclick="exportTechnical()">Export connected records</button>`);}
function openMaterialReceipt(){if(!chainGuard(["stores"]))return;chainForm("Receive material lot or controlled tool","saveMaterialReceipt()",`<label for="chain_part">Registered material / tool</label><select id="chain_part">${STORE.parts.filter(p=>["Controlled tool","Consumable / standard part"].includes(p.category)).map(p=>`<option value="${esc(p.pn)}">${esc(p.pn)} · ${esc(p.category)}</option>`).join("")}</select>${chainFields([["serial","Lot / asset serial"],["qty","Received quantity (tools: 1)","number","1"],["supplier","Supplier"],["reference","Goods receipt / conformity evidence"],["expiry","Shelf expiry / control due date","date",relativeDate(365)]])}`);}
function saveMaterialReceipt(){if(!chainGuard(["stores"]))return;const p=STORE.parts.find(p=>p.pn===chainValue("part")),serial=chainValue("serial"),qty=Number(chainValue("qty")),expiry=chainValue("expiry"),ref=chainValue("reference");if(!p||!serial||!Number.isInteger(qty)||qty<1||!validQualityDate(expiry)||!ref||!chainValue("supplier")||STORE.materialLots.some(l=>l.pn===p.pn&&l.lot.toLowerCase()===serial.toLowerCase())||STORE.resources.some(r=>r.serial?.toLowerCase()===serial.toLowerCase())){chainFail(Error("Use a registered model, unique lot/asset, whole quantity, source evidence and valid expiry."));return;}if(p.category==="Controlled tool"){if(qty!==1){chainFail(Error("Register tools one serial at a time."));return;}STORE.resources.push({id:chainId("TOOL"),name:p.name,pn:p.pn,serial,kind:"Tool",condition:"Available",receiptReference:ref,supplier:chainValue("supplier"),controlDue:expiry,...chainActor()});}else STORE.materialLots.push({id:chainId("LOT"),pn:p.pn,lot:serial,received:qty,qty,expiry,reference:ref,supplier:chainValue("supplier"),condition:"Quarantined",issues:[],...chainActor()});auditOps("Material / equipment receipt",serial,ref);closeModal();route("#intake");}
function openLotInspect(id){if(!chainGuard(["inspector"]))return;chainForm("Inspect material lot",`saveLotInspect('${id}')`,chainFields([["reference","Conformity / shelf-life evidence"],["notes","Packaging, identity and condition findings","textarea"]]));}
function saveLotInspect(id){if(!chainGuard(["inspector"]))return;const l=STORE.materialLots.find(x=>x.id===id);try{if(!l||l.condition!=="Quarantined"||l.expiry<=demoDate)throw Error("Expired or non-quarantined lots cannot be accepted.");l.inspection=chainEvidence("Lot accepted",chainValue("reference"),chainValue("notes"));}catch(e){chainFail(e);return;}l.condition="Serviceable";STORE.parts.find(p=>p.pn===l.pn).stock+=l.qty;auditOps("Material lot inspected",l.lot,l.inspection.reference);closeModal();route("#intake");}
function openLotIssue(id){if(!chainGuard(["stores"]))return;chainForm("Issue traceable material lot",`saveLotIssue('${id}')`,chainFields([["qty","Quantity","number","1"],["reference","Work package / work order"],["notes","Aircraft, task and recipient","textarea"]]));}
function saveLotIssue(id){if(!chainGuard(["stores"]))return;const l=STORE.materialLots.find(x=>x.id===id),qty=Number(chainValue("qty"));try{if(!l||l.condition!=="Serviceable"||l.expiry<=demoDate||!Number.isInteger(qty)||qty<1||qty>l.qty)throw Error("Issue requires a current accepted lot and available whole quantity.");const evidence=chainEvidence("Material issued",chainValue("reference"),chainValue("notes"));l.issues.push({...evidence,qty});l.qty-=qty;STORE.parts.find(p=>p.pn===l.pn).stock-=qty;}catch(e){chainFail(e);return;}auditOps("Material issued",l.lot,`${qty}; ${chainValue("reference")}`);closeModal();route("#intake");}
function viewDepartmentChain(){const rows=ENGINEERING_TEAMS.map(t=>`<tr><td><b>${esc(t.name)}</b><small class="table-sub">${esc(t.user)} · ${["stores","engineer","inspector"].includes(t.role)?"Existing demo password":"demo123"}</small></td><td>${esc(t.owns)}</td><td>${esc(t.next)}</td></tr>`).join("");$("viewSub").textContent="Department ownership, handoff queues and evidence from the same stores-originated equipment record.";$("viewActions").innerHTML='<button class="btn" onclick="exportTechnical()">Export department records</button>';$("viewBody").innerHTML=`<div class="eng-metrics">${engMetric("Receipt verification",STORE.components.filter(c=>c.intakeId&&!c.recordsVerified).length,"Technical records queue")}${engMetric("Work packages",STORE.workPackages.filter(w=>w.status!=="Archived").length,"Planning → execution → certification")}${engMetric("Shop / repair loop",STORE.shopOrders.filter(s=>s.status!=="Returned").length,"External custody tracked")}${engMetric("Shift handovers",STORE.handovers.filter(h=>!h.acknowledged).length,"Receiving team acknowledgement")}</div><div class="workflow-strip"><span>Demand / procurement</span><span>Receipt / source records</span><span>Inspection / serviceable stores</span><span>Planning / issue / work</span><span>Checks / certification / archive</span><span>Removal / shop / return or scrap</span></div><div class="row"><button class="btn" onclick="route('#intake')">Stores intake</button><button class="btn" onclick="route('#supply')">Supply & repair</button><button class="btn" onclick="route('#work-packages')">Work packages</button><button class="btn" onclick="route('#handover')">Shift handover</button><button class="btn" onclick="route('#engineering-support')">Engineering support</button></div>${engPanel("Roles, ownership & handoff",engTable(["Team / demo account","Responsibility","Handoff to"],rows))}<p class="form-note">Standard airline engineering model, not a verified Air Zimbabwe organisation chart. Qualified NDT and metrology are represented through the existing Laboratory and Calibration workflows. Operational release requires actual approved procedures and personnel authorisations.</p>`;}
function openPurchase(){if(!chainGuard(["procurement"]))return;chainForm("Procurement: register supply order","savePurchase()",`<label for="chain_part">Part demand</label><select id="chain_part">${STORE.parts.map(p=>`<option value="${esc(p.pn)}">${esc(p.pn)} · ${esc(p.name)}</option>`).join("")}</select>${chainFields([["ref","Purchase order"],["supplier","Supplier"],["approval","Supplier approval / evaluation reference"],["qty","Ordered quantity","number","1"],["eta","Expected delivery","date",relativeDate(7)],["reason","Demand / AOG / work order reference","textarea"]])}`);}
function savePurchase(){if(!chainGuard(["procurement"]))return;const p={ref:chainValue("ref"),pn:chainValue("part"),supplier:chainValue("supplier"),approval:chainValue("approval"),qty:Number(chainValue("qty")),eta:chainValue("eta"),reason:chainValue("reason"),status:"Ordered",receipts:[],...chainActor()};if(!p.ref||STORE.purchaseOrders.some(x=>x.ref.toLowerCase()===p.ref.toLowerCase())||!p.supplier||!p.approval||!Number.isInteger(p.qty)||p.qty<1||!validQualityDate(p.eta)||!p.reason){chainFail(Error("Complete a unique order, supplier evaluation, whole quantity, delivery date and demand reference."));return;}STORE.purchaseOrders.push(p);auditOps("Supply order registered",p.ref,p.reason);closeModal();route("#supply");}
function viewSupply(){ $("viewSub").textContent="Supplier evidence, incoming orders, external repair custody and return-to-quarantine. Receipt never resets total life.";$("viewActions").innerHTML=session.role==="procurement"?'<button class="btn btn-accent" onclick="openPurchase()">+ Supply order</button>':"";$("viewBody").innerHTML=`${engPanel("Supply orders & receiving reconciliation",engTable(["Order / part","Supplier / evaluation","Quantity / ETA","Received serials"],STORE.purchaseOrders.map(p=>`<tr><td>${esc(p.ref)}<small class="table-sub">${esc(p.pn)}</small></td><td>${esc(p.supplier)}<small class="table-sub">${esc(p.approval)}</small></td><td>${p.qty} / ${esc(p.eta)}</td><td>${esc(p.receipts.join(", ")||"Awaiting stores receipt")}</td></tr>`).join("")))}${engPanel("Removed components: disposition queue",engTable(["Serial / removal","Current custody","Action"],STORE.components.filter(c=>c.reg==="Stores"&&c.condition!=="Serviceable").map(c=>`<tr><td>${esc(c.sn)}<small class="table-sub">${esc(c.removalReason||"Receiving quarantine")}</small></td><td>${esc(intakeStage(c))}</td><td>${session.role==="stores"&&!c.shopOpen&&!c.scrapped?`<button class="btn btn-sm" onclick="openShopDispatch('${c.sn}')">Repair dispatch</button>`:""}${session.role==="inspector"&&!c.shopOpen&&!c.scrapped?`<button class="btn btn-sm" onclick="openScrap('${c.sn}')">Scrap segregation</button>`:""}</td></tr>`).join("")))}${engPanel("Repair / workshop orders",engTable(["Order / serial","Vendor / work","Status","Action"],STORE.shopOrders.map(s=>`<tr><td>${esc(s.ref)} / ${esc(s.sn)}</td><td>${esc(s.vendor)}<small class="table-sub">${esc(s.reason)}</small></td><td>${engTag(s.status,"info")}</td><td>${session.role==="workshop"&&s.status==="Dispatched"?`<button class="btn btn-sm" onclick="openShopReport('${s.ref}')">Shop report</button>`:""}${session.role==="stores"&&s.status==="Report ready"?`<button class="btn btn-sm" onclick="openShopReturn('${s.ref}')">Receive return</button>`:""}</td></tr>`).join("")))}`;}
function openShopDispatch(sn){if(!chainGuard(["stores"]))return;chainForm("Dispatch removed component for repair",`saveShopDispatch('${sn}')`,chainFields([["reference","Repair order / dispatch reference"],["vendor","Workshop / approved vendor"],["approval","Vendor capability / approval reference"],["notes","Repair demand, packaging and custody","textarea"]]));}
function dispatchShop(c,reference,vendor,approval,notes){if(c.reg!=="Stores"||c.condition!=="Quarantined"||c.shopOpen||c.scrapped)throw Error("Dispatch requires a quarantined, non-scrapped serial in stores custody.");const evidence=chainEvidence("Repair dispatch",reference,notes);if(!safeWorkflowRef(reference)||!vendor||!approval||STORE.shopOrders.some(s=>s.ref===reference))throw Error("Enter vendor approval and a unique repair order.");const s={ref:reference,sn:c.sn,vendor,approval,reason:notes,status:"Dispatched",dispatch:evidence};STORE.shopOrders.push(s);c.shopOpen=reference;c.condition="In repair";c.position=`External custody: ${vendor}`;return s;}
function saveShopDispatch(sn){if(!chainGuard(["stores"]))return;const c=STORE.components.find(x=>x.sn===sn);try{dispatchShop(c,chainValue("reference"),chainValue("vendor"),chainValue("approval"),chainValue("notes"));}catch(e){chainFail(e);return;}recordMovement("Repair dispatched",c,"Stores quarantine",chainValue("vendor"),chainValue("reference"));closeModal();route("#supply");}
function openShopReport(ref){if(!chainGuard(["workshop"]))return;chainForm("Workshop: record completed work & tests",`saveShopReport('${ref}')`,`${chainFields([["reference","Shop report / release document"],["notes","Work carried out and test evidence","textarea"]])}<label for="chain_overhaul">Work scope</label><select id="chain_overhaul"><option value="repair">Repair / inspection — preserve counters</option><option value="overhaul">Documented full overhaul — start new interval</option></select>`);}
function saveShopReport(ref){if(!chainGuard(["workshop"]))return;const s=STORE.shopOrders.find(x=>x.ref===ref);try{if(!s||s.status!=="Dispatched")throw Error("This repair order is not awaiting a report.");s.report=chainEvidence("Shop report",chainValue("reference"),chainValue("notes"));s.overhaul=chainValue("overhaul")==="overhaul";}catch(e){chainFail(e);return;}s.status="Report ready";auditOps("Shop report recorded",s.sn,`${ref}: ${s.report.reference}`);closeModal();route("#supply");}
function openShopReturn(ref){if(!chainGuard(["stores"]))return;chainForm("Stores: receive repair return",`saveShopReturn('${ref}')`,chainFields([["reference","Return goods receipt"],["notes","Serial, report, packaging and custody check","textarea"]]));}
function receiveShopReturn(s,reference,notes){const c=STORE.components.find(c=>c.sn===s.sn);if(s.status!=="Report ready"||!c||c.shopOpen!==s.ref||c.scrapped)throw Error("Receive only the reported, dispatched serial; scrapped records cannot return.");s.returnEvidence=chainEvidence("Repair return",reference,notes);if(s.overhaul)applyComponentLog(c,{hours:0,cycles:0,flights:0},true);c.release=s.report.reference;c.historyReference=s.report.reference;c.recordsVerified=false;c.reg="Stores";c.condition="Quarantined";c.position="Repair return quarantine";c.stockCounted=false;delete c.inspectedBy;delete c.issue;delete c.shopOpen;c.intakeId=c.intakeId||chainId("RETURN");c.supplier=c.supplier||s.vendor;c.po=s.ref;c.limitSource=c.limitSource||"Seeded demo maintenance source";c.limitRevision=c.limitRevision||"DEMO";c.controlMode=c.controlMode||"Life-controlled";s.status="Returned";return c;}
function saveShopReturn(ref){if(!chainGuard(["stores"]))return;const s=STORE.shopOrders.find(x=>x.ref===ref);let c;try{c=receiveShopReturn(s,chainValue("reference"),chainValue("notes"));}catch(e){chainFail(e);return;}recordMovement("Repair return",c,s.vendor,"Return quarantine",chainValue("reference"));closeModal();route("#intake");}
function openScrap(sn){if(!chainGuard(["inspector"]))return;chainForm("Record unsalvageable / scrap segregation",`saveScrap('${sn}')`,`${chainFields([["reference","Approved disposition / life-limit evidence"],["notes","Reason and segregated storage location","textarea"]])}<p>Records segregation only; physical mutilation/disposal must follow approved procedures. This serial will be blocked from inspection, repair dispatch and installation.</p>`);}
function saveScrap(sn){if(!chainGuard(["inspector"]))return;const c=STORE.components.find(x=>x.sn===sn);try{if(!c||c.reg!=="Stores"||c.shopOpen||c.scrapped)throw Error("Scrap disposition requires stores custody and no active shop order.");c.scrapEvidence=chainEvidence("Scrap segregated",chainValue("reference"),chainValue("notes"));}catch(e){chainFail(e);return;}if(c.stockCounted)STORE.parts.find(p=>p.pn===c.pn).stock--;c.stockCounted=false;c.scrapped=true;c.condition="Scrapped";c.position="Segregated scrap";auditOps("Scrap segregated",sn,c.scrapEvidence.reference);closeModal();route("#supply");}
function openWorkPackage(){if(!chainGuard(["planner"]))return;chainForm("Planning: create controlled work package","saveWorkPackage()",`<label for="chain_reg">Aircraft</label><select id="chain_reg">${STORE.fleet.map(a=>`<option>${a.reg}</option>`).join("")}</select><label for="chain_serial">Component demand</label><select id="chain_serial"><option value="">No replacement · inspection / maintenance task</option>${STORE.components.filter(c=>c.reg==="Stores"&&!c.scrapped&&!c.shopOpen).map(c=>`<option>${esc(c.sn)}</option>`).join("")}</select><label for="chain_engineer">Assigned engineer</label><select id="chain_engineer">${STORE.users.filter(u=>u.role==="engineer").map(u=>`<option value="${u.user}">${esc(u.name)}</option>`).join("")}</select><label for="chain_plan">Resource / bay / tool plan</label><select id="chain_plan">${STORE.jobs.filter(j=>j.status!=="Complete").map(j=>`<option value="${esc(j.id)}">${esc(j.wo)} · ${esc(j.reg)}</option>`).join("")}</select>${chainFields([["ref","Unique work package reference"],["position","Installation position"],["data","Maintenance instruction / AMM / task-card reference"],["revision","Instruction revision"],["task","Task scope and safety / access / isolation requirements","textarea"]])}<p>Package readiness is checked against inspector life review, resource planning and outstanding engineering instructions. Stores must allocate the exact serial before fitment.</p>`);}
function createWorkPackage(w){const c=STORE.components.find(c=>c.sn===w.sn),plan=STORE.jobs.find(j=>j.id===w.plan);if(!safeWorkflowRef(w.ref)||STORE.workPackages.some(x=>x.ref===w.ref)||(w.sn&&!w.position)||!w.data||!w.revision||!w.task||(w.sn&&(!c||c.reg!=="Stores"||c.scrapped||c.shopOpen))||!STORE.fleet.some(a=>a.reg===w.reg)||!STORE.users.some(u=>u.user===w.engineer&&u.role==="engineer"))throw Error("Complete a unique package, component, position, approved-data revision and engineer.");if(!plan||plan.reg!==w.reg||plan.engineer!==w.engineer||plan.status==="Complete")throw Error("Select an open resource plan for this aircraft and engineer.");w.status="Awaiting control";w.history=[{action:"Package planned",reference:w.data,notes:w.task,...chainActor()}];STORE.workPackages.push(w);return w;}
function saveWorkPackage(){if(!chainGuard(["planner"]))return;const w={ref:chainValue("ref"),reg:chainValue("reg"),sn:chainValue("serial"),engineer:chainValue("engineer"),plan:chainValue("plan"),position:chainValue("position"),data:chainValue("data"),revision:chainValue("revision"),task:chainValue("task"),...chainActor()};try{createWorkPackage(w);}catch(e){chainFail(e);return;}auditOps("Work package planned",w.sn,w.ref);closeModal();route("#work-packages");}
function workGate(w){const c=STORE.components.find(c=>c.sn===w.sn),p=STORE.jobs.find(j=>j.id===w.plan);if(w.sn&&(!c||c.scrapped||c.shopOpen||c.reg!=="Stores"||c.condition!=="Serviceable"||lifeReviewState(c)!=="Reviewed current record"||componentState(c).status==="OVERDUE"||adverseLabOpen(c.sn)))throw Error("Package needs the exact serviceable serial and current verified life evidence.");if(!p||p.reg!==w.reg||p.engineer!==w.engineer||!currentCalibration(p.tool,p.end.slice(0,10)).usable)throw Error("A matching resource plan with valid tooling is required.");if(w.sn&&STORE.workPackages.some(x=>x.ref!==w.ref&&x.sn===w.sn&&!["Archived","Cancelled"].includes(x.status)&&x.issued))throw Error("This serial is allocated to another package.");return c;}
function openPackageStep(ref,step){const roles={authorise:["control"],issue:["stores"],perform:["engineer"],inspect:["inspector"],certify:["certifier"],archive:["records"]};if(!chainGuard(roles[step]||[]))return;chainForm(`Department handoff: ${step}`,`savePackageStep('${ref}','${step}')`,chainFields([["reference",step==="certify"?"Demo certification / authority reference":"Task / work / handoff evidence reference"],["notes",step==="perform"?"Task completion, checks, tests and any outstanding items":"Assessment and handoff notes","textarea"]])+`${step==="inspect"?[["identity","Serial fitment and task-card evidence checked"],["tests","Functional / leak / operational test evidence checked"],["tools","Tool accountability, FOD and access close-out checked"],["openItems","Outstanding items and maintenance limitations reviewed"]].map(([k,label])=>`<label><input id="chain_check_${k}" type="checkbox" required> ${label}</label>`).join(""):""}<p class="form-note">${step==="certify"?"Records demonstration completion only. This does not issue an operational certificate of release to service.":"Each transition is attributed to the signed-in departmental account."}</p>`);}
function packageStep(w,step,reference,notes,checks={}){const rules={authorise:{role:"control",from:"Awaiting control",to:"Awaiting stores issue"},issue:{role:"stores",from:"Awaiting stores issue",to:"Issued to engineer"},perform:{role:"engineer",from:"Issued to engineer",to:"Awaiting independent check"},inspect:{role:"inspector",from:"Awaiting independent check",to:"Awaiting certification"},certify:{role:"certifier",from:"Awaiting certification",to:"Completed demo review"},archive:{role:"records",from:"Completed demo review",to:"Archived"}},r=rules[step];if(!r||session.role!==r.role||w.status!==r.from)throw Error("Wrong departmental role or handoff order.");const evidence=chainEvidence(step,reference,notes);const c=STORE.components.find(c=>c.sn===w.sn);if(["authorise","issue"].includes(step))workGate(w);if(step==="issue"&&c){const part=STORE.parts.find(p=>p.pn===c.pn);if(part&&!part.category)part.stock--;w.issued={...evidence};c.issue={package:w.ref,reg:w.reg,position:w.position,...evidence};}if(step==="perform"){if(session.user!==w.engineer)throw Error("Only the assigned engineer can complete this package.");const p=STORE.jobs.find(j=>j.id===w.plan);if(!p||p.status!=="Complete")throw Error("Complete the linked resource work plan before task handoff.");if(w.sn&&(c?.reg!==w.reg||c.position!==w.position||c.lastFitmentPackage!==w.ref))throw Error("Record fitment of the issued serial at the package position first.");w.performedBy=session.user;}if(step==="inspect"){if(w.performedBy===session.user)throw Error("The independent checker must be a different person.");if(w.sn&&(!c||componentState(c).status==="OVERDUE"||adverseLabOpen(c.sn)||lifeReviewState(c)!=="Reviewed current record"))throw Error("Resolve component life or laboratory findings before independent acceptance.");if(!["identity","tests","tools","openItems"].every(k=>checks[k]===true))throw Error("Confirm task evidence, functional tests, tool/FOD close-out and outstanding-item review.");if(!currentCalibration(STORE.jobs.find(j=>j.id===w.plan)?.tool).usable)throw Error("Resolve current tool calibration or impact review before independent acceptance.");w.inspection={...evidence,checks};}if(step==="certify"){if(!w.inspection||STORE.defects.some(d=>d.reg===w.reg&&d.status==="Open"&&!validDeferral(d))||STORE.aog.some(a=>a.reg===w.reg&&a.step<3)||STORE.instructions.some(i=>i.reg===w.reg&&i.status!=="Closed"&&i.mandatory&&i.due<=demoDate))throw Error("Unresolved defects, AOG or mandatory instructions prevent demonstration completion review.");if(w.sn&&(!c||componentState(c).status==="OVERDUE"||adverseLabOpen(c.sn)||lifeReviewState(c)!=="Reviewed current record"))throw Error("Current component limits, inspector life evidence and findings require review.");w.certification=evidence;}w.history.push(evidence);w.status=r.to;return w;}
function savePackageStep(ref,step){const w=STORE.workPackages.find(w=>w.ref===ref);try{if(!w)throw Error("Package not found.");packageStep(w,step,chainValue("reference"),chainValue("notes"),step==="inspect"?Object.fromEntries(["identity","tests","tools","openItems"].map(k=>[k,$("chain_check_"+k).checked])):{});}catch(e){chainFail(e);return;}auditOps(`Package ${step}`,w.sn,`${w.ref}: ${chainValue("reference")}`);closeModal();route("#work-packages");}
function viewWorkPackages(){ $("viewSub").textContent="Approved-data revision → control authorisation → stores serial allocation → assigned engineer → independent inspection → demo certification → records archive.";$("viewActions").innerHTML=session.role==="planner"?'<button class="btn btn-accent" onclick="openWorkPackage()">+ Work package</button><button class="btn" onclick="openPlan()">+ Resource plan</button>':"";const steps={"Awaiting control":["control","authorise"],"Awaiting stores issue":["stores","issue"],"Issued to engineer":["engineer","perform"],"Awaiting independent check":["inspector","inspect"],"Awaiting certification":["certifier","certify"],"Completed demo review":["records","archive"]};$("viewBody").innerHTML=engPanel("Controlled work packages",engTable(["Package / aircraft","Demand / data","Owner / status","Next handoff"],STORE.workPackages.map(w=>{const next=steps[w.status];return `<tr><td><b>${esc(w.ref)}</b><small class="table-sub">${esc(w.reg)}</small></td><td>${esc(w.sn||"Inspection / maintenance task")} · ${esc(w.position||"No replacement")}<small class="table-sub">${esc(w.data)} rev ${esc(w.revision)}</small></td><td>${esc(next?.[0]||"Technical records")}<small class="table-sub">${engTag(w.status,"info")}</small></td><td><button class="btn btn-sm" onclick="openPackageHistory('${w.ref}')">Evidence</button>${next?.[0]===session.role?`<button class="btn btn-sm" onclick="openPackageStep('${w.ref}','${next[1]}')">${esc(next[1])}</button>`:""}</td></tr>`;}).join("")));}
function openPackageHistory(ref){const w=STORE.workPackages.find(w=>w.ref===ref);engineeringModal("Work package evidence",`<h3>${esc(ref)} · ${esc(w.reg)}</h3><p>${esc(w.task)}</p><p>Assigned engineer: ${esc(w.engineer)} · resource plan: ${esc(w.plan)}</p>${engTable(["Timestamp","Handoff / reference","Person / evidence"],w.history.map(e=>`<tr><td>${esc(e.at)}</td><td>${esc(e.action)}<small class="table-sub">${esc(e.reference)}</small></td><td>${esc(e.by)}<small class="table-sub">${esc(e.notes)}</small></td></tr>`).join(""))}`);}
const installBeforeIssue=validateInstall;
validateInstall=function(c,reg,position,components=STORE.components){installBeforeIssue(c,reg,position,components);if(c.intakeId){const w=STORE.workPackages.find(w=>w.ref===c.issue?.package);if(!w||w.status!=="Issued to engineer"||w.reg!==reg||w.position!==position||w.engineer!==session.user)throw Error("Stores must issue this serial through an authorised package to the assigned engineer and position.");}return true;};
const saveInstallBeforePackage=saveInstall;
saveInstall=function(sn){const c=STORE.components.find(c=>c.sn===sn);if(!c?.intakeId){saveInstallBeforePackage(sn);return;}if(!requireEngineer())return;const reg=$("installReg").value,position=$("installPosition").value.trim(),ref=$("installWork").value.trim();try{validateInstall(c,reg,position);if(!ref)throw Error("Enter fitment work evidence.");}catch(e){$("installError").textContent=e.message;return;}c.lastFitmentPackage=c.issue.package;c.reg=reg;c.position=position;c.condition="Installed";recordMovement("Installed",c,"Issued stores serial",reg+" / "+position,ref);closeModal();route("#lifecycle");};
const removeBeforeIssue=saveRemoval;
saveRemoval=function(sn){const c=STORE.components.find(c=>c.sn===sn),before=c?.reg;removeBeforeIssue(sn);if(c&&before!=="Stores"&&c.reg==="Stores"){c.stockCounted=false;delete c.issue;delete c.lastFitmentPackage;persistOps();}};
function openHandover(){chainForm("Record outgoing shift / departmental handover","saveHandover()",`<label for="chain_to">Receiving person / team</label><select id="chain_to">${STORE.users.filter(u=>u.user!==session.user).map(u=>`<option value="${u.user}">${esc(u.name)} · ${esc(u.role)}</option>`).join("")}</select>${chainFields([["reference","Aircraft / package / component reference"],["notes","Completed work, open tasks, hazards, isolation and outstanding parts","textarea"]])}`);}
function saveHandover(){const to=chainValue("to");try{if(!STORE.users.some(u=>u.user===to)||to===session.user)throw Error("Choose a different receiving account.");const evidence=chainEvidence("Shift handover",chainValue("reference"),chainValue("notes"));STORE.handovers.unshift({id:chainId("HANDOVER"),to,...evidence,acknowledged:false});auditOps("Shift handover recorded",evidence.reference,`${to}: ${evidence.notes}`);}catch(e){chainFail(e);return;}closeModal();route("#handover");}
function acknowledgeHandover(id){const h=STORE.handovers.find(h=>h.id===id);if(!h||h.to!==session.user||h.acknowledged){toast("warn","Receiving team","Only the named receiving person can acknowledge.");return;}h.acknowledged=true;h.acknowledgedBy=session.user;h.acknowledgedAt=new Date().toISOString();auditOps("Handover acknowledged",h.reference,h.notes);route("#handover");}
function viewHandover(){ $("viewSub").textContent="Open work, hazards, isolation, parts and records transfer to a named receiving account. Acknowledgement is separate from task completion.";$("viewActions").innerHTML='<button class="btn btn-accent" onclick="openHandover()">+ Shift handover</button>';$("viewBody").innerHTML=engPanel("Shift / department handover log",engTable(["Reference / outgoing person","Receiving person","Outstanding information","Acknowledgement"],STORE.handovers.map(h=>`<tr><td>${esc(h.reference)}<small class="table-sub">${esc(h.by)} · ${esc(h.at)}</small></td><td>${esc(h.to)}</td><td>${esc(h.notes)}</td><td>${h.acknowledged?engTag("Acknowledged","ok"):engTag("Awaiting recipient","warnb")}${h.to===session.user&&!h.acknowledged?`<button class="btn btn-sm" onclick="acknowledgeHandover('${h.id}')">Acknowledge</button>`:""}</td></tr>`).join("")));}
function viewEngineeringSupport(){ $("viewSub").textContent="Engineering instructions, mandatory applicability review and repeat-removal evidence feed planning and maintenance control.";$("viewActions").innerHTML=["records","reliability"].includes(session.role)?'<button class="btn btn-accent" onclick="openInstruction()">+ AD / SB / engineering action</button>':"";$("viewBody").innerHTML=`${engPanel("Engineering instruction / applicability register",engTable(["Instruction / aircraft","Applicability / due","Status","Action"],STORE.instructions.map(i=>`<tr><td>${esc(i.ref)}<small class="table-sub">${esc(i.reg)} · ${i.mandatory?"Mandatory":"Engineering action"}</small></td><td>${esc(i.notes)}<small class="table-sub">Due ${esc(i.due)}</small></td><td>${engTag(i.status,i.status==="Closed"?"ok":"warnb")}</td><td>${session.role==="records"&&i.status!=="Closed"?`<button class="btn btn-sm" onclick="openInstructionClose('${i.id}')">Verify accomplishment</button>`:""}</td></tr>`).join("")))}${engPanel("Reliability: recorded removal evidence",engTable(["Part number","Removal count","Serial / reason"],STORE.parts.map(p=>{const movements=STORE.movements.filter(m=>m.pn===p.pn&&m.action==="Removed");if(!movements.length)return "";return `<tr><td>${esc(p.pn)}<small class="table-sub">${esc(p.name)}</small></td><td>${movements.length}</td><td>${esc(movements.map(m=>m.sn).join(", "))}</td></tr>`;}).join("")))}<p class="form-note">This register captures reviewed applicability; it is not an automatic AD feed, approved MEL deferral or statistical reliability programme. Raw removal counts are not failure rates without exposure and event classification.</p>`;}
function openInstruction(){if(!chainGuard(["records","reliability"]))return;chainForm("Record engineering instruction & applicability","saveInstruction()",`<label for="chain_reg">Aircraft</label><select id="chain_reg">${STORE.fleet.map(a=>`<option>${a.reg}</option>`).join("")}</select>${chainFields([["reference","AD / SB / engineering instruction and revision"],["due","Required accomplishment date","date",relativeDate(30)],["notes","Applicability, requirement and work-package reference","textarea"]])}<label><input id="chain_mandatory" type="checkbox"> Mandatory instruction (unresolved blocks demo completion review)</label>`);}
function saveInstruction(){if(!chainGuard(["records","reliability"]))return;try{const evidence=chainEvidence("Instruction registered",chainValue("reference"),chainValue("notes"));if(!validQualityDate(chainValue("due")))throw Error("Use a valid due date.");STORE.instructions.unshift({id:chainId("INST"),ref:evidence.reference,reg:chainValue("reg"),notes:evidence.notes,due:chainValue("due"),mandatory:$("chain_mandatory").checked,status:"Open",...chainActor()});auditOps("Engineering instruction",evidence.reference,evidence.notes);}catch(e){chainFail(e);return;}closeModal();route("#engineering-support");}
function openInstructionClose(id){if(!chainGuard(["records"]))return;chainForm("Verify instruction accomplishment",`saveInstructionClose('${id}')`,chainFields([["reference","Accomplishment / task evidence"],["notes","Verification and remaining requirements","textarea"]]));}
function saveInstructionClose(id){if(!chainGuard(["records"]))return;const i=STORE.instructions.find(i=>i.id===id);try{if(!i||i.status==="Closed")throw Error("Instruction is not open.");i.accomplishment=chainEvidence("Accomplishment verified",chainValue("reference"),chainValue("notes"));}catch(e){chainFail(e);return;}i.status="Closed";auditOps("Instruction accomplishment verified",i.ref,i.accomplishment.reference);closeModal();route("#engineering-support");}
function viewFlightRecords(){ $("viewSub").textContent="Flight operations records actual hours, cycles and flights. Maintenance control reconciles each source once; the captured fitted serials receive the utilisation.";$("viewActions").innerHTML=session.role==="flightops"?'<button class="btn btn-accent" onclick="openFlightReport()">+ Flight utilisation source</button>':"";$("viewBody").innerHTML=engPanel("Flight-sector utilisation & technical-log handoff",engTable(["Source / tail / date","Recorded usage","Captured fitted serials","Control reconciliation"],STORE.flightReports.map(f=>`<tr><td>${esc(f.ref)}<small class="table-sub">${esc(f.reg)} · ${esc(f.date)}</small></td><td>${f.hours} FH / ${f.cycles} FC / ${f.flights} flights</td><td>${esc(f.installed.map(c=>c.sn).join(", "))}</td><td>${engTag(f.status,f.status==="Applied"?"ok":"warnb")}${session.role==="control"&&f.status==="Submitted"?`<button class="btn btn-sm" onclick="openFlightApply('${f.ref}')">Reconcile & post</button>`:""}<small class="table-sub">${esc(f.review?.reference||"")}</small></td></tr>`).join("")))+`<p class="form-note">Capture the source immediately against the actual fitted configuration. Late entry across a prior fitment change requires records reconciliation; the system does not infer which serial flew. Recording utilisation is not dispatch authorisation.</p>`;}
function openFlightReport(){if(!chainGuard(["flightops"]))return;chainForm("Flight crew: record utilisation source","saveFlightReport()",`<label for="chain_reg">Aircraft</label><select id="chain_reg">${STORE.fleet.map(a=>`<option>${a.reg}</option>`).join("")}</select>${chainFields([["reference","Unique sector / crew technical-log source"],["date","Operation date","date",demoDate],["hours","Actual flight hours","number","1"],["cycles","Actual flight cycles","number","1"],["flights","Actual flights","number","1"],["notes","Sector, source evidence and crew remarks","textarea"]])}<label><input id="chain_check" type="checkbox" required> Fitted configuration matches the operation being recorded</label>`);}
function submitFlightReport(f){if(!STORE.fleet.some(a=>a.reg===f.reg)||!safeWorkflowRef(f.ref)||STORE.flightReports.some(x=>x.ref.toUpperCase()===f.ref.toUpperCase())||!validQualityDate(f.date)||f.date>demoDate||![f.hours,f.cycles,f.flights].every(v=>Number.isFinite(v)&&v>=0)||!Number.isInteger(f.cycles)||!Number.isInteger(f.flights)||f.hours+f.cycles+f.flights===0||!f.notes)throw Error("Use a unique source, valid operation date and non-negative actual usage; cycles and flights are whole numbers.");f.installed=STORE.components.filter(c=>c.reg===f.reg).map(c=>({sn:c.sn,overhaul:c.lastOverhaul}));f.status="Submitted";STORE.flightReports.unshift(f);return f;}
function saveFlightReport(){if(!chainGuard(["flightops"])||!$("chain_check").checked)return;const f={ref:chainValue("reference"),reg:chainValue("reg"),date:chainValue("date"),hours:Number(chainValue("hours")),cycles:Number(chainValue("cycles")),flights:Number(chainValue("flights")),notes:chainValue("notes"),...chainActor()};try{submitFlightReport(f);}catch(e){chainFail(e);return;}auditOps("Flight source submitted",f.reg,f.ref);closeModal();route("#flight-records");}
function openFlightApply(ref){if(!chainGuard(["control"]))return;chainForm("Maintenance control: reconcile flight utilisation",`saveFlightApply('${ref}')`,chainFields([["reference","Reconciled tech-log / flight record reference"],["notes","Source, fitted configuration and usage checks","textarea"]]));}
function applyFlightReport(f,reference,notes){if(session.role!=="control"||f.status!=="Submitted")throw Error("Maintenance control may post a submitted source once.");const review=chainEvidence("Flight source reconciled",reference,notes),a=STORE.fleet.find(a=>a.reg===f.reg);if(!a)throw Error("Aircraft record missing.");const components=f.installed.map(i=>{const c=STORE.components.find(c=>c.sn===i.sn);if(!c||c.lastOverhaul!==i.overhaul)throw Error("A captured serial has changed overhaul interval; records reconciliation is required before posting.");return c;});a.hours=Math.round((a.hours+f.hours)*10000)/10000;a.cycles+=f.cycles;a.due=Math.max(0,a.due-f.hours);for(const c of components){c.hours=Math.round((c.hours+f.hours)*10000)/10000;c.totalHours=Math.round((c.totalHours+f.hours)*10000)/10000;c.cycles+=f.cycles;c.totalCycles+=f.cycles;c.flights+=f.flights;c.totalFlights+=f.flights;}f.review=review;f.status="Applied";return f;}
function saveFlightApply(ref){if(!chainGuard(["control"]))return;const f=STORE.flightReports.find(f=>f.ref===ref);try{if(!f)throw Error("Source missing.");applyFlightReport(f,chainValue("reference"),chainValue("notes"));}catch(e){chainFail(e);return;}auditOps("Flight utilisation applied",f.reg,`${f.ref}: +${f.hours} FH / +${f.cycles} FC / +${f.flights} flights`);closeModal();route("#flight-records");}
function validDeferral(defect,date=demoDate){return STORE.deferrals.some(d=>d.defect===defect.ref&&d.status==="Reviewed demo deferral"&&d.due>date&&d.approval);}
function viewDeferrals(){ $("viewSub").textContent="Maintenance control records an operator-MEL reference and rectification deadline; certifying staff reviews the evidence. Deferrals never extend component life limits or override ADs.";$("viewActions").innerHTML=session.role==="control"?'<button class="btn btn-accent" onclick="openDeferral()">+ Deferral assessment</button>':"";$("viewBody").innerHTML=engPanel("Controlled defect deferral register",engTable(["Assessment / defect","Operator MEL / item","Deadline / conditions","Review"],STORE.deferrals.map(d=>`<tr><td>${esc(d.ref)}<small class="table-sub">${esc(d.defect)} · ${esc(d.reg)}</small></td><td>${esc(d.manual)} rev ${esc(d.revision)}<small class="table-sub">${esc(d.item)}</small></td><td>${esc(d.due)}<small class="table-sub">${esc(d.limitations)} · ${esc(d.plan)}</small></td><td>${engTag(d.due<=demoDate?"Deadline reached":d.status,d.due<=demoDate?"danger":"warnb")}${session.role==="certifier"&&d.status==="Requested"?`<button class="btn btn-sm" onclick="openDeferralReview('${d.ref}')">Review evidence</button>`:""}</td></tr>`).join("")))+`<p class="form-note">Deadline and conditions are transcribed from the applicable operator-approved source, not calculated from a generic category. The demo retains a limitations-review flag in flight assessment; it does not authorise dispatch or validate an MEL.</p>`;}
function openDeferral(){if(!chainGuard(["control"]))return;chainForm("Control: request documented deferral assessment","saveDeferral()",`<label for="chain_defect">Open defect</label><select id="chain_defect">${STORE.defects.filter(d=>d.status==="Open").map(d=>`<option value="${esc(d.ref)}">${esc(d.ref)} · ${esc(d.reg)}</option>`).join("")}</select>${chainFields([["reference","Unique deferral assessment reference"],["manual","Operator-approved MEL / procedure reference"],["revision","Approved revision"],["item","Applicable item and category"],["due","Transcribed rectification deadline","date",relativeDate(3)],["limitations","Operating / maintenance conditions and required actions","textarea"],["plan","Rectification work package / plan reference"]])}`);}
function saveDeferral(){if(!chainGuard(["control"]))return;const defect=STORE.defects.find(d=>d.ref===chainValue("defect")),d={ref:chainValue("reference"),defect:chainValue("defect"),reg:defect?.reg,manual:chainValue("manual"),revision:chainValue("revision"),item:chainValue("item"),due:chainValue("due"),limitations:chainValue("limitations"),plan:chainValue("plan"),status:"Requested",...chainActor()};if(!defect||defect.status!=="Open"||!safeWorkflowRef(d.ref)||STORE.deferrals.some(x=>x.ref===d.ref)||![d.manual,d.revision,d.item,d.limitations,d.plan].every(Boolean)||!validQualityDate(d.due)||d.due<=demoDate){chainFail(Error("Select an open defect and complete unique reference, approved source, conditions, work plan and future deadline."));return;}STORE.deferrals.push(d);auditOps("Deferral assessment requested",d.defect,d.ref);closeModal();route("#deferrals");}
function openDeferralReview(ref){if(!chainGuard(["certifier"]))return;chainForm("Certifying staff: review deferral evidence",`saveDeferralReview('${ref}')`,`${chainFields([["reference","Applicability / condition evidence reference"],["notes","Evidence of required maintenance actions and operating limitations","textarea"]])}<label><input id="chain_check" type="checkbox" required> Approved-source applicability, deadline and required conditions checked</label>`);}
function reviewDeferral(d,reference,notes){if(session.role!=="certifier"||d.status!=="Requested"||d.due<=demoDate)throw Error("A current requested assessment requires certifying-staff review.");const approval=chainEvidence("Demo deferral reviewed",reference,notes);if(STORE.instructions.some(i=>i.reg===d.reg&&i.mandatory&&i.status!=="Closed"&&i.due<=demoDate)||STORE.components.some(c=>c.reg===d.reg&&componentState(c).status==="OVERDUE"))throw Error("Mandatory instruction or component life exceedance cannot be bypassed by a deferral.");d.approval=approval;d.status="Reviewed demo deferral";return d;}
function saveDeferralReview(ref){if(!chainGuard(["certifier"])||!$("chain_check").checked)return;const d=STORE.deferrals.find(d=>d.ref===ref);try{if(!d)throw Error("Deferral not found.");reviewDeferral(d,chainValue("reference"),chainValue("notes"));}catch(e){chainFail(e);return;}auditOps("Deferral evidence reviewed",d.defect,`${d.ref}: ${d.approval.reference}`);closeModal();route("#deferrals");}
const engineeringBeforeInstructions=aircraftState;
aircraftState=function(a){const base=engineeringBeforeInstructions(a);if(STORE.instructions.some(i=>i.reg===a.reg&&i.mandatory&&i.status!=="Closed"&&i.due<=demoDate))return "INSTRUCTION DUE";return base;};
const flightBeforeInstructions=flightAssessment;
flightAssessment=function(reg,hours,cycles,date){const reasons=flightBeforeInstructions(reg,hours,cycles,date);if(STORE.instructions.some(i=>i.reg===reg&&i.mandatory&&i.status!=="Closed"&&i.due<=date))reasons.push("Mandatory engineering instruction due");return [...new Set(reasons)];};
const calibrationBeforeAssetIdentity=validateCalibration;
validateCalibration=function(c){calibrationBeforeAssetIdentity(c);const tool=STORE.resources.find(r=>r.id===c.tool);if(tool?.serial&&tool.serial.toUpperCase()!==c.serial.toUpperCase())throw Error("Certificate serial must match the stores-registered equipment serial.");return c;};
const planBeforeOnCondition=planFromComponent;
planFromComponent=function(sn){const c=STORE.components.find(c=>c.sn===sn),rate=STORE.planningRates[c.reg]||{hours:4,cycles:2};if(forecastComponent(c,rate.hours,rate.cycles).days===null){toast("info","On-condition component","Plan from the approved condition or inspection requirement; no fixed removal date is recorded.");return;}planBeforeOnCondition(sn);};
const overviewBeforeDepartment=viewEngineeringDashboard;
viewEngineeringDashboard=function(){overviewBeforeDepartment();const team=ENGINEERING_TEAMS.find(t=>t.role===session.role);$("viewBody").insertAdjacentHTML("afterbegin",`<div class="chain-next"><b>${esc(team?.name||session.title)}</b><p>${esc(team?.owns||"Departmental engineering work")}</p><div class="row"><button class="btn" onclick="route('#department-chain')">Teams & handoffs</button><button class="btn" onclick="route('#intake')">Equipment intake</button><button class="btn" onclick="route('#work-packages')">Work packages</button><button class="btn" onclick="route('#flight-records')">Flight records</button></div></div>`);};
exportTechnical=function(){const data={schema:"tslms-department-records-v3",exportedAt:new Date().toISOString(),roleModel:ENGINEERING_TEAMS};for(const key of CHAIN_KEYS)data[key]=STORE[key];const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:"application/json"}));const a=document.createElement("a");a.href=url;a.download="tslms-department-records.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function selectDepartmentAccount(user){const u=STORE.users.find(u=>u.user===user);if(!u)return;$("loginUser").value=u.user;$("loginPass").value=u.pass;document.querySelectorAll(".role-card").forEach(c=>c.classList.toggle("active",c.dataset.user===user));}
if($("departmentRole"))$("departmentRole").innerHTML='<option value="">Choose a team or person…</option>'+STORE.users.map(u=>`<option value="${u.user}">${esc(u.name)}${u.name!==u.title?" · "+esc(u.title):""}</option>`).join("");
